hardpointShader['vertexShader']='\x0a\x0avarying\x20vec2\x20vUv;\x0a\x0avoid\x20main()\x20{\x0a\x0avUv\x20=\x20uv;\x0a\x0a#include\x20<begin_vertex>\x0a#include\x20<project_vertex>\x0a\x0a}\x0a\x0a',hardpointShader["fragmentShader"]="\n\nuniform sampler2D noise;\nuniform float time;\nuniform vec3 color;\n\nvarying vec2 vUv;\n\nvec4 blend( vec4 a, vec4 b ) {\nreturn vec4( vec3( a ) * a.a + vec3( b ) * ( 1.0 - a.a ), 1.0 );\n}\n\nvoid main() {\ngl_FragColor = vec4( color, 1.0 );\ngl_FragColor.a = 1.0 - vUv.y;\nif( gl_FragColor.a > 0.87 ) {\ngl_FragColor.a = 0.8; // 0.9\n} else {\nvec2 uv = vUv;\nuv.x *= 5.0 * 2.5;\nuv.xy /= 3.0;\nuv.y -= time / 8.5;\nfloat num = texture2D( noise, uv ).x;\n//float offset = mod( time / 2.0, 1.0 );\nfloat offset = vUv.y;\nnum += offset;\nif( num > 1.0 ) {\nnum -= 1.0;\n}\nif( num < 0.3 ) {\ngl_FragColor.a *= 0.6;\n} else if( num < 0.65 ) {\ngl_FragColor.a *= 0.8;\n}\n\ngl_FragColor.a *= 0.5; // 0.7\n}\n}\n";
